<?php declare(strict_types=1); $fields=['Email'=>'email','Phone'=>'phone','Country'=>'country','Interest'=>'interest','Location'=>'location','Budget'=>'budget','Timeline'=>'timeline','Preferred contact'=>'method','Best time'=>'best_time','Listing'=>'listing_title','Source'=>'source_url']; ?>
<div class="mb-5"><a class="text-sm font-semibold text-navy-700" href="<?= e(admin_url('inbox')) ?>">← Back to inbox</a></div>
<div class="grid gap-6 xl:grid-cols-3"><div class="space-y-6 xl:col-span-2"><section class="card p-6"><div class="flex flex-wrap justify-between gap-3"><div><span class="badge bg-gold-100 text-gold-600"><?= e($enquiry['type']) ?></span><h2 class="mt-3 t-h3"><?= e($enquiry['name']) ?></h2><p class="t-meta text-muted"><?= e(nice_date($enquiry['created_at'])) ?></p></div><span class="badge bg-navy-100 text-navy-700"><?= e($enquiry['status']) ?></span></div><?php if($enquiry['message']): ?><div class="mt-6 whitespace-pre-wrap rounded-[6px] bg-canvas p-5 text-[0.9375rem]"><?= e($enquiry['message']) ?></div><?php endif; ?><dl class="mt-6 grid gap-4 sm:grid-cols-2"><?php foreach($fields as $label=>$key): if(empty($enquiry[$key])) continue; ?><div><dt class="field-label"><?= e($label) ?></dt><dd class="break-words text-sm"><?= e($enquiry[$key]) ?></dd></div><?php endforeach; ?></dl></section>
<section class="card p-6"><h2 class="t-h3 text-[1.0625rem]">Internal notes</h2><div class="mt-4 space-y-3"><?php if(!$notes): ?><p class="text-sm text-muted">No notes yet.</p><?php endif; ?><?php foreach($notes as $note): ?><div class="rounded-[6px] bg-canvas p-4"><p class="whitespace-pre-wrap text-sm"><?= e($note['body']) ?></p><p class="mt-2 t-meta text-muted"><?= e($note['user_name'] ?: 'Former staff') ?> · <?= e(nice_date($note['created_at'])) ?></p></div><?php endforeach; ?></div><?php if(can('inbox.manage')): ?><form class="mt-5" method="post" action="<?= e(admin_url('inbox/'.$enquiry['id'].'/note')) ?>"><?= csrf_field() ?><textarea class="field h-auto py-3" rows="3" name="body" maxlength="5000" required placeholder="Add an internal note…"></textarea><button class="btn btn-primary mt-3">Add note</button></form><?php endif; ?></section></div>
<aside class="space-y-6"><?php if(can('inbox.manage')): ?><form class="card p-5" method="post" action="<?= e(admin_url('inbox/'.$enquiry['id'].'/assign')) ?>"><?= csrf_field() ?><label class="field-label">Assigned to</label><select class="field" name="assigned_to"><option value="0">Unassigned</option><?php foreach($users as $staff): ?><option value="<?= $staff['id'] ?>" <?= (int)$enquiry['assigned_to']===(int)$staff['id']?'selected':'' ?>><?= e($staff['name']) ?></option><?php endforeach; ?></select><button class="btn btn-primary mt-4 w-full">Save assignment</button></form><form class="card p-5" method="post" action="<?= e(admin_url('inbox/'.$enquiry['id'].'/status')) ?>"><?= csrf_field() ?><label class="field-label">Status</label><select class="field" name="status"><?php foreach(['new','assigned','replied','closed'] as $s): ?><option <?= $enquiry['status']===$s?'selected':'' ?>><?= $s ?></option><?php endforeach; ?></select><button class="btn btn-primary mt-4 w-full">Update status</button></form><?php endif; ?></aside></div>
